const item = $input.first();
const tier = item.json.args[0].toLowerCase();
const prefix = tier === 'sweetpea' ? 'FAM-' : 'PEA-';
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let code = prefix;
for (let i = 0; i < 8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
item.json.code = code;
item.json.tier = tier;
return [item];

const row = $input.first().json;
const tierName = row.tier === 'sweetpea' ? '🌸 Sweet Pea' : '🌱 Seedling';
const statusEmoji = row.status === 'active' ? '🟢' : (row.status === 'suspended' ? '🔴' : '🟡');
const text = `👤 *DONOR PROFILE*
══════════════════════════

🏷 Name:      ${row.name}
🆔 Username:  @${row.username}
📧 Email:     ${row.email}
📊 Status:    ${statusEmoji} ${row.status.toUpperCase()}
🎟 Tier:      ${tierName}`;
return [{ json: { text } }];

const item = $input.first();
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%';
let pwd = '';
for (let i = 0; i < 16; i++) pwd += chars.charAt(Math.floor(Math.random() * chars.length));
item.json.temp_password = pwd;
return [item];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO ACTIVE DONORS*
──────────────────────────

There are no active donors.' } }];
let text = `📊 *ACTIVE DONORS*
══════════════════════════

🟢 ${rows.length} donor${rows.length !== 1 ? 's' : ''}

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸' : '🌱';
  text += `• *${r.name}* (@${r.username}) ${tier}
`;
});
return [{ json: { text: text.trim() } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO DONORS FOUND*
──────────────────────────' } }];
let text = `👥 *ALL DONORS*
══════════════════════════

📋 ${rows.length} total

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸 Sweet Pea' : '🌱 Seedling';
  const statusEmoji = r.status === 'active' ? '🟢' : '🔴';
  text += `• *${r.name}* (@${r.username})
  ├─ ${statusEmoji} ${r.status}
  └─ ${tier}

`;
});
return [{ json: { text: text.trim() } }];

const r = $input.first().json;
const text = `📊 *DATABASE DASHBOARD*
══════════════════════════

👥 *Donors*
   ├─ Total:      ${r.total_donors}
   ├─ 🟢 Active:   ${r.active_donors}
   ├─ 🔴 Suspended: ${r.suspended_donors}
   └─ ⏳ Pending:   ${r.pending_donors}

🔑 *Invite Codes*
   ├─ Total:      ${r.total_codes}
   ├─ 🟢 Available: ${r.available_codes}
   └─ 🔴 Used:      ${r.used_codes}`;
return [{ json: { text } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO CODES FOUND*
──────────────────────────' } }];
let text = `🔑 *ALL INVITE CODES*
══════════════════════════

📋 ${rows.length} total

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸 Sweet Pea' : '🌱 Seedling';
  const status = r.used ? `🔴 Used by *${r.used_by || 'unknown'}*` : '🟢 Available';
  text += `• \`${r.code}\`
  ├─ ${tier}
  └─ ${status}

`;
});
return [{ json: { text: text.trim() } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO AVAILABLE CODES*
──────────────────────────

Generate one with /invite' } }];
let text = `🟢 *AVAILABLE CODES*
══════════════════════════

🎟 ${rows.length} ready to use

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸 Sweet Pea' : '🌱 Seedling';
  text += `• \`${r.code}\`
  └─ ${tier}

`;
});
return [{ json: { text: text.trim() } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO USED CODES*
──────────────────────────

No codes have been redeemed yet.' } }];
let text = `🔴 *REDEEMED CODES*
══════════════════════════

📋 ${rows.length} total

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸 Sweet Pea' : '🌱 Seedling';
  const date = r.used_at ? new Date(r.used_at).toLocaleDateString() : 'unknown';
  text += `• \`${r.code}\`
  ├─ ${tier}
  ├─ 👤 By: *${r.used_by || '?'}*
  └─ 📅 Redeemed: ${date}

`;
});
return [{ json: { text: text.trim() } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '🔍 *NO RESULTS*
──────────────────────────

Try a different search term.' } }];
let text = `🔍 *SEARCH RESULTS*
══════════════════════════

📋 ${rows.length} match${rows.length !== 1 ? 'es' : ''}

`;
rows.forEach((r) => {
  const statusEmoji = r.status === 'active' ? '🟢' : '🔴';
  const tier = r.tier === 'sweetpea' ? '🌸' : '🌱';
  text += `• *${r.name}* (@${r.username}) ${tier}
  ├─ 📧 ${r.email}
  └─ ${statusEmoji} ${r.status}

`;
});
return [{ json: { text: text.trim() } }];

const r = $input.first().json;
const text = `🗄️ *DATABASE STATUS*
══════════════════════════

✅ *Connected*

🏷 Name:   ${r.db_name}
📊 Tables: ${r.table_count}
💾 Size:   ${r.db_size}

📋 *Table Rows*
   ├─ 👥 Donors:        ${r.donors}
   ├─ 📝 Subscribers:   ${r.subscribers}
   ├─ 🎟 Invite Codes:  ${r.invite_codes}
   ├─ 🚨 Incidents:     ${r.incidents}
   └─ 📡 Telegram:      ${r.telegram_offset}`;
return [{ json: { text } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO DONORS*
──────────────────────────

Nothing to delete.' } }];
let text = `🗑️ *DELETE DONOR*
══════════════════════════

Usage: /delsub <username or email>

Or tap a command below:

`;
rows.forEach((r) => { const id = r.username || r.email; text += `• /delsub \`${id}\` · *${r.name}*
`; });
return [{ json: { text: text.trim() } }];

const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) return [{ json: { text: '📭 *NO CODES*
──────────────────────────

Nothing to delete.' } }];
let text = `🗑️ *DELETE INVITE CODE*
══════════════════════════

Usage: /delcode <code>

Or tap a command below:

`;
rows.forEach((r) => {
  const tier = r.tier === 'sweetpea' ? '🌸' : '🌱';
  const status = r.used ? '🔴 Used' : '🟢 Available';
  text += `• /delcode \`${r.code}\` · ${tier} · ${status}
`;
});
return [{ json: { text: text.trim() } }];

// Plain HTML, every database value escaped: Telegram parses entities in this
// mode, so one bare < or & used to kill the whole reply.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(r => r.is_real);
if (rows.length === 0) {
  return [{ json: { text: '<b>NO PENDING DONORS</b>\n──────────────────────────\n\nNo donors awaiting verification.' } }];
}
let text = `<b>PENDING DONORS</b>\n══════════════════════════\n\n⏳ ${rows.length} awaiting verification\n\n`;
rows.forEach((r) => {
  const date = new Date(r.created_at).toLocaleDateString();
  text += `• ID: ${esc(r.id)} — <b>${esc(r.name)}</b> (@${esc(r.username)})\n`
        + `  ├─ 📧 ${esc(r.email)}\n`
        + `  ├─ 💰 $${esc(r.donation_amount)} (${esc(r.crypto_type || 'N/A')})\n`
        + `  ├─ 🔗 TX: ${r.transaction_hash ? esc(String(r.transaction_hash).substring(0, 20)) + '...' : 'not provided'}\n`
        + `  └─ 📅 ${esc(date)}\n\n`;
});
text += 'Use /verify &lt;id&gt; to approve or /reject &lt;id&gt; to reject.';
return [{ json: { text: text.trim() } }];

const item = $input.first();
const args = ($('Parse Command').item.json.args || []);
const asked = String(args[1] || '').toLowerCase();
const donorTier = String(item.json.tier || 'sweetpea').toLowerCase();
const tier = (asked === 'sweetpea' || asked === 'seedling') ? asked : donorTier;
// prefix follows the tier, same rule as /invite: family (sweetpea) -> FAM-
const prefix = tier === 'sweetpea' ? 'FAM-' : 'PEA-';
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let code = prefix;
for (let i = 0; i < 8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
item.json.invite_code = code;
item.json.tier = tier;
return [item];

const args = $json.args || [];
const rest = (args.join(' ') || '').trim();
if (!rest) {
  return [{ json: { listMode: true } }];
}
const comma = rest.indexOf(',');
const title = (comma > -1 ? rest.slice(0, comma) : rest).trim();
const description = comma > -1 ? rest.slice(comma + 1).trim() : '';
if (title.length < 3) {
  return [{ json: { reply: 'Title must be at least 3 characters.' } }];
}
return [{ json: { title, description, listMode: false } }];

const args = $json.args || [];
const id = (args[0] || '').trim();
if (!id || !/^\d+$/.test(id)) {
  return [{ json: { reply: 'Usage: /resolve <incident_id>' } }];
}
return [{ json: { incident_id: parseInt(id, 10), reply: null } }];

const rows = $input.all();
const first = rows[0] && rows[0].json;
if (!first || !first.title) {
  return [{ json: { reply: 'No incident found with that ID.' } }];
}
return [{ json: { reply: 'Incident resolved: ' + first.title } }];

const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [{ json: { reply: 'No incidents found.' } }];
let text = '🚨 *INCIDENTS*\n══════════════════════════\n\n';
rows.forEach(r => {
  const s = r.status === 'resolved' ? '✅ Resolved' : '🔴 Active';
  text += `• ID ${r.id}: *${r.title}* — ${s}\n`;
});
return [{ json: { reply: text.trim() } }];

// Parse: /delinc <id>
// Parse Command already strips the command word into args (e.g. ['5'])
const args = $json.args || [];
const id = (args[0] || '').trim();
if (!id || !/^\d+$/.test(id)) {
  return [{ json: { reply: 'Usage: /delinc <incident_id>' } }];
}
return [{ json: { incident_id: parseInt(id, 10), reply: null } }];

const rows = $input.all();
const first = rows[0] && rows[0].json;
if (!first || !first.deleted) {
  return [{ json: { reply: 'No incident found with that ID.' } }];
}
return [{ json: { reply: 'Incident deleted: ' + first.title } }];

const update = $input.first().json.body || $input.first().json;
const msg = update.message;
const ADMIN_ID = 6485376162;
if (!msg || !msg.text || msg.from?.id !== ADMIN_ID) {
  return [{ json: { command: '__noop__' } }];
}
const text = msg.text.trim();
const chatId = msg.chat?.id;
const fromId = msg.from?.id;
const parts = text.split(/\s+/);
const cmd = parts[0].replace('/', '').toLowerCase();
const VALID = ['start','help','invite','refer','status','resend','suspend','unsuspend','list','allsubs','count','allcodes','available','usedcodes','search','dbstatus','delsub','delcode','pending','verify','reject','incident','resolve','delinc'];
return [{ json: { command: VALID.includes(cmd) ? cmd : 'unknown', args: parts.slice(1), chatId, fromId, rawText: text } }];

const item = $input.first();
const TIERS = { fam: 'sweetpea', sweetpea: 'sweetpea', pea: 'seedling', seedling: 'seedling' };
let args = (item.json.args || []).slice();
let tier = 'sweetpea';
const head = String(args[0] || '').toLowerCase();
if (TIERS[head]) { tier = TIERS[head]; args = args.slice(1); }
const label = args.join(' ').trim().slice(0, 60);
const prefix = tier === 'sweetpea' ? 'FAM-' : 'PEA-';
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let code = prefix;
for (let i = 0; i < 8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
return [{ json: { ...item.json, code, tier, label } }];

const j = ($input.first() || {}).json || {};
const rows = Array.isArray(j.referrals) ? j.referrals : (j.body && Array.isArray(j.body.referrals) ? j.body.referrals : []);
let text = '🌿 *REFERRALS*\n──────────────────────────\n\n';
if (!rows.length) { text += 'No pending referrals.\n'; }
else {
  rows.slice(0, 10).forEach((r) => {
    let d = '';
    try { d = ' · ' + new Date(r.at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); } catch (e) {}
    text += '• *' + r.name + '* — ' + r.service + '\n   by ' + (r.byName || '?') + d + '\n';
  });
  if (rows.length > 10) text += '\n_' + (rows.length - 10) + ' more pending._\n';
}
text += '\nUsage: `/refer [fam|pea] <name>`\nMints a code for one of the above.';
return [{ json: { text } }];
